import Foundation

/// A real recognition result for the onboarding sample page, replayed on first launch so the
/// app does not need to load the models before the user has started.
/// Generated by KotenOCRTests/OnboardingSampleGenerator.swift; do not edit the JSON by hand.
struct OnboardingSample: Codable {
    struct Line: Codable {
        /// x1, y1, x2, y2, normalized to the image size (0...1).
        let box: [Double]
        let text: String
    }

    let source: String
    /// True if auto-deskew rotated the page; then the boxes would not match the shipped image.
    let rotated: Bool
    /// In reading order.
    let lines: [Line]

    static func load() -> OnboardingSample? {
        guard let url = Bundle.main.url(forResource: "onboarding_sample_ocr", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(OnboardingSample.self, from: data)
    }
}
